package dev.zomboid.isotacz;
import net.minecraft.client.Minecraft;import com.cleannrooster.dungeons_iso.mod.Mod;
public class ShotChecks32{
 static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}public static class Player{public float yaw,pitch,yBodyRot;public boolean gun=true;public Object getMainHandItem(){return gun;}public CursorTarget.Vec getEyePosition(){return new CursorTarget.Vec(0,1.6,0);}public float getXRot(){return pitch;}public float getYRot(){return yaw;}public float getYHeadRot(){return yaw;}public void setXRot(float v){pitch=v;}public void setYRot(float v){yaw=v;}public void setYHeadRot(float v){}}public static class Callback{public boolean canceled;public void cancel(){canceled=true;}}
 public static void main(String[]args){var mc=Minecraft.INSTANCE;var p=new Player();mc.player=p;for(int i=0;i<80;i++){double a=i*.13;CursorTarget.target=new CursorTarget.Vec(Math.sin(a)*20,2+Math.cos(a),Math.cos(a)*20);p.yaw=45;p.pitch=45;ShotAim32.before();double[]want=Rules.angles(CursorTarget.target.x(),CursorTarget.target.y()-1.6,CursorTarget.target.z());ok(Math.abs(Rules.wrap(p.yaw-want[0]))<.001&&Math.abs(p.pitch-want[1])<.001,"before-shot native player direction follows changing cursor, not stale camera");var cb=new Callback();ShotAim32.external(cb);ok(cb.canceled,"external shoulder handler blocked while iso owns aim");}
 AimStability.treating=true;ok(!ShotAim32.owns(),"medical animations retain control");AimStability.treating=false;Mod.enabled=false;p.yaw=67;ShotAim32.before();ok(p.yaw==67,"first person and lateral camera retain native aim");var cb=new Callback();ShotAim32.external(cb);ok(!cb.canceled,"shoulder handler preserved outside iso");Mod.enabled=true;p.gun=false;ok(!ShotAim32.owns(),"non-gun input preserved");p.gun=true;mc.screen=new Object();ok(!ShotAim32.owns(),"menus do not aim or intercept external handlers");mc.screen=null;mc.level=null;ok(!ShotAim32.owns(),"world unload ignored");mc.level=new Object();mc.player=null;ok(!ShotAim32.owns(),"missing player ignored");System.out.println("ACTUAL_ISO_BRIDGE_PRE_SHOT_CURSOR_DIRECTION_EXTERNAL_HANDLER_SCOPE_CHECKS="+n);}
}
